import { DomainModels, SelectorResult, StudioProApi } from "@mendix/extensions-api";
import { Agent, Variable } from "../../types/agent";
import { calculateVariables } from "../../utils/agentUtils";


export const handleAgentChangeEvent = (studioPro: StudioProApi, field: keyof Agent, agent: Agent, setAgent: React.Dispatch<React.SetStateAction<Agent>>, documentId: string) => async (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
) => {
    console.log("agent change triggered for field ", field)
    if (field === "userPrompt" || field === "systemPrompt") {
        const updatedAgent = { ...agent, [field]: e.target.value };
        const newVariables: Variable[] = calculateVariables(updatedAgent);
        const updatedAgentWithVariables = { ...updatedAgent, variables: newVariables }
        setAgent(updatedAgentWithVariables);
        await updateAgentDocument(studioPro, updatedAgentWithVariables, documentId);
    }
    else {
        const updatedAgent = { ...agent, [field]: e.target.value }
        setAgent(updatedAgent);
        await updateAgentDocument(studioPro, updatedAgent, documentId);
    }
};


