import { RadioButton } from '@mendix/ide-ui-components/radiobutton/RadioButton';
import { RadioButtonGroup } from '@mendix/ide-ui-components/radiobutton/RadioButtonGroup';
import { DivFlexColumn, DivFlexRow, StyledLabel } from './elements/formelements';


interface RadioButtonGroupProps {
    label?: string;
    ariaLabel: string;
    value: string;
    options: {caption: string; value: string}[];
    onChange: (value: string) => void;
    hasMarginTop?: boolean;
}



const RadioButtonGroupLabeled: React.FC<RadioButtonGroupProps> = ({
    label,
    ariaLabel,
    options,
    value,
    onChange,
    hasMarginTop = false,
}) => {
    const marginTop = hasMarginTop ? 8 : 0;

    
    return (
        <DivFlexRow marginTop={marginTop}>
            {label && (
                <DivFlexColumn>
                    <StyledLabel>
                        {label}
                    </StyledLabel>
                </DivFlexColumn>
            )}
            <DivFlexColumn fullWidth>
                <RadioButtonGroup
                    value={value}
                    onChange={onChange}
                    aria-label={ariaLabel}
                >
                    {options.map((o) => {
                        return (
                            <RadioButton
                                value={o.value}
                                aria-label={o.caption}
                                key={o.value}
                            >
                                {o.caption}
                            </RadioButton>
                        )
                    })}
                </RadioButtonGroup>
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default RadioButtonGroupLabeled;